<!doctype html><html lang="da"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ticket #{{ $ticket->id }} · Nodexa</title><style>*{box-sizing:border-box}body{margin:0;background:#090b10;color:#f6f7fb;font-family:Inter,system-ui,sans-serif}.wrap{max-width:1000px;margin:0 auto;padding:35px 20px}.back{color:#9d90ff;text-decoration:none}.head{display:flex;justify-content:space-between;gap:20px;align-items:center;margin:20px 0}.badge{background:#171c27;border:1px solid #2b3242;padding:8px 12px;border-radius:20px}.card{background:#11151d;border:1px solid #252b39;border-radius:14px;padding:20px;margin:14px 0}.msg.staff{border-left:3px solid #745cff}.meta{color:#929bad;font-size:13px;margin-bottom:10px}.text{white-space:pre-wrap;line-height:1.55}textarea{width:100%;min-height:130px;background:#0c0f15;border:1px solid #303748;color:white;border-radius:10px;padding:14px;font:inherit}.actions{display:flex;justify-content:space-between;gap:10px;margin-top:12px}.btn{border:0;border-radius:9px;padding:11px 16px;background:#745cff;color:#fff;font-weight:700;cursor:pointer}.danger{background:#242936;color:#d7dbe5}@media(max-width:600px){.head,.actions{align-items:flex-start;flex-direction:column}}</style></head><body><main class="wrap"><a class="back" href="/client#tickets">← Tilbage til tickets</a><div class="head"><div><h1>#{{ $ticket->id }} · {{ $ticket->subject }}</h1><div style="color:#929bad">{{ ucfirst($ticket->department) }} · {{ ucfirst($ticket->priority) }} prioritet</div></div><span class="badge">{{ str_replace('_',' ',ucfirst($ticket->status)) }}</span></div>@foreach($messages as $message)<article class="card msg {{ $message->staff ? 'staff' : '' }}"><div class="meta">{{ $message->staff ? 'Nodexa Support' : ($user->username ?? $user->email) }} · {{ $message->created_at }}</div><div class="text">{{ $message->message }}</div></article>@endforeach@if($ticket->status !== 'closed')<section class="card"><h3>Svar på ticket</